use ieee.std_logic_1164.all;
use ieee.std_logic_textio.all;

use std.textio.all;
use std.env.all;

entity harness is
end entity harness;

architecture sim of harness is
    signal bin_sig  : std_logic_vector(3 downto 0);
    signal gray_sig : std_logic_vector(3 downto 0);
begin
    dut : entity work.solution
        port map (
            bin => bin_sig,
            gray => gray_sig
        );

    process
        variable in_line  : line;
        variable out_line : line;
        variable bin_in   : std_logic_vector(3 downto 0);
    begin
        readline(input, in_line);
        read(in_line, bin_in);
        bin_sig <= bin_in;
        wait for 1 ns;
        write(out_line, gray_sig);
        writeline(output, out_line);
        finish;
    end process;
end architecture sim;

generator.source:
"""Random 4-bit values for the VHDL Binary to Gray Code testbench.

Only the input is produced here -- the expected output is captured by
running the reference solution's own simulation, so the two can never
disagree. All 16 possible inputs exist, so this leans on a few by name
rather than trying to look clever about coverage.
"""

WIDTH = 4


def _bits(value):
    return "".join(str((value >> b) & 1) for b in range(WIDTH - 1, -1, -1))


def _case(name, value, description=""):
    return {"name": name, "stdin": _bits(value) + "\n", "description": description}


def generate(rng, count):
    return [_case("random value #%d" % (i + 1), rng.randrange(1 << WIDTH))
            for i in range(count)]
